/**
 * Unit tests for XmlSerializerProvider copy constructor.
 * Since the constructor is protected, we use reflection to access it.
 */
public class XmlSerializerProvider_XmlSerializerProvider_TriageGen1Test {

    @Test
    @SuppressWarnings("unchecked")
    public void testProtectedConstructor_CopiesRootNameLookup() throws Exception {
        // Arrange
        XmlRootNameLookup mockLookup = Mockito.mock(XmlRootNameLookup.class);

        // We need an instance of XmlSerializerProvider to pass as 'src'
        // Since it is a provider, we can use a subclass or use the public constructor via reflection if available
        // However, the requirement is to test the protected constructor (src)

        // Create the source instance using the public constructor: XmlSerializerProvider(XmlRootNameLookup rootNames)
        Constructor<XmlSerializerProvider> publicConstructor = XmlSerializerProvider.class.getDeclaredConstructor(XmlRootNameLookup.class);
        publicConstructor.setAccessible(true);
        XmlSerializerProvider src = publicConstructor.newInstance(mockLookup);

        // Prepare the protected constructor: XmlSerializerProvider(XmlSerializerProvider src)
        Constructor<XmlSerializerProvider> protectedConstructor = XmlSerializerProvider.class.getDeclaredConstructor(XmlSerializerProvider.class);
        protectedConstructor.setAccessible(true);

        // Act
        XmlSerializerProvider target = protectedConstructor.newInstance(src);

        // Assert
        assertNotNull("Target instance should not be null", target);

        // Use reflection to check the private field _rootNameLookup
        java.lang.reflect.Field field = XmlSerializerProvider.class.getDeclaredField("_rootNameLookup");
        field.setAccessible(true);

        XmlRootNameLookup srcLookup = (XmlRootNameLookup) field.get(src);
        XmlRootNameLookup targetLookup = (XmlRootNameLookup) field.get(target);

        assertNotNull("Source lookup should not be null", srcLookup);
        assertSame("The _rootNameLookup should be the same instance (shallow copy as per implementation)", 
            srcLookup, targetLookup);
    }

    @Test
    @SuppressWarnings("unchecked")
    public void testProtectedConstructor_WithNullLookup() throws Exception {
        // Arrange
        Constructor<XmlSerializerProvider> publicConstructor = XmlSerializerProvider.class.getDeclaredConstructor(XmlRootNameLookup.class);
        publicConstructor.setAccessible(true);
        XmlSerializerProvider src = publicConstructor.newInstance(null);

        Constructor<XmlSerializerProvider> protectedConstructor = XmlSerializerProvider.class.getDeclaredConstructor(XmlSerializerProvider.class);
        protectedConstructor.setAccessible(true);

        // Act
        XmlSerializerProvider target = protectedConstructor.newInstance(src);

        // Assert
        java.lang.reflect.Field field = XmlSerializerProvider.class.getDeclaredField("_rootNameLookup");
        field.setAccessible(true);

        assertNull("Target lookup should be null if source lookup was null", field.get(target));
    }
}
